9: /** Degenerate axes fall back to +Y so authored data can never stall a spinner. */
10: export function normalizeAxis(axis: Vec3): Vec3 {
11:   const length = Math.hypot(axis.x, axis.y, axis.z);
12:   if (!Number.isFinite(length) || length < EPSILON) return { ...DEFAULT_AXIS };
13:   return { x: axis.x / length, y: axis.y / length, z: axis.z / length };
